<script setup lang="ts">
import { CopyDocument, Delete, Plus } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { onMounted, ref } from 'vue'

import { deleteHyperparameterTemplate, listHyperparameterTemplates, type HyperparameterTemplate } from '../api/hyperparameters'

const templates = ref<HyperparameterTemplate[]>([]); const loading = ref(false); const deleting = ref(''); const error = ref('')
async function load(){loading.value=true;try{templates.value=await listHyperparameterTemplates()}catch(reason){error.value=reason instanceof Error?reason.message:'模板列表加载失败'}finally{loading.value=false}}
async function remove(item:HyperparameterTemplate){try{await ElMessageBox.confirm(`删除超参数模板“${item.name}”？`,'删除模板',{type:'warning',confirmButtonText:'删除模板',cancelButtonText:'取消'})}catch{return}deleting.value=item.id;try{await deleteHyperparameterTemplate(item.id);templates.value=templates.value.filter(value=>value.id!==item.id);ElMessage.success('模板已删除。')}catch(reason){ElMessage.error(reason instanceof Error?reason.message:'模板删除失败')}finally{deleting.value=''}}
onMounted(load)
</script>
<template><main class="content-page template-page"><header class="content-toolbar"><div class="content-toolbar-title"><h1>超参数模板</h1><span>{{ templates.length }} 个模板</span></div><router-link to="/hyperparameter-templates/new"><el-button type="primary" :icon="Plus">新建模板</el-button></router-link></header><div v-loading="loading" class="content-body"><el-alert v-if="error" :title="error" type="error" :closable="false" /><section class="template-list"><header class="template-row"><span>模板</span><span>epochs</span><span>batch</span><span>image size</span><span>创建时间</span><span /></header><article v-for="item in templates" :key="item.id" class="template-row"><div><strong>{{ item.name }}</strong><el-tag v-if="item.system_key" size="small" effect="plain">系统</el-tag><p>{{ item.description||'暂无描述' }}</p></div><code>{{ item.epochs }}</code><code>{{ item.batch_mode==='auto'?'auto':item.batch_value }}</code><code>{{ item.image_size }}</code><time>{{ item.created_at.slice(0,10) }}</time><div class="actions"><router-link :to="`/hyperparameter-templates/${item.id}`">详情</router-link><router-link :to="`/hyperparameter-templates/new?from=${item.id}`"><el-button link :icon="CopyDocument">派生</el-button></router-link><el-button v-if="item.can_manage" type="danger" link :icon="Delete" :loading="deleting===item.id" @click="remove(item)">删除</el-button></div></article><el-empty v-if="!loading&&!templates.length" description="还没有超参数模板" /></section></div></main></template>
<style scoped>.template-page{background:#f4f7fa;color:#17212b}.template-list{margin-top:24px;background:#fff;border:1px solid #d8dee6}.template-row{display:grid;grid-template-columns:minmax(250px,1fr) 80px 80px 100px 110px 220px;gap:16px;align-items:center;padding:16px 20px;border-bottom:1px solid #e5e9ef}.template-list>header{color:#687482;font-size:12px;background:#f8fafc}.template-row>div:first-child{min-width:0}.template-row strong{margin-right:8px}.template-row p{margin:5px 0 0;color:#687482;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.actions{display:flex;gap:8px;align-items:center}.actions a{color:#2563eb;text-decoration:none}@media(max-width:900px){.template-row{grid-template-columns:1fr auto}.template-row>:nth-child(2),.template-row>:nth-child(3),.template-row>:nth-child(4),.template-row>:nth-child(5),.template-list>header{display:none}}</style>
